/**
 * Regression gate: the docs left sidebar is generated by
 * @rspress/plugin-auto-nav-sidebar, which rspress only registers when the user
 * config does NOT define themeConfig.nav/sidebar by hand (see rspress core:
 * `if (!haveNavSidebarConfig)`). If that plugin is missing or aborts, every
 * page still builds "successfully" but renders an empty left menu.
 * This check fails the build when built pages carry an empty sidebar.
 */
import { readdirSync, readFileSync, statSync } from "node:fs";
import { join } from "node:path";

const docBuild = new URL("../doc_build", import.meta.url).pathname;
let pages = 0;
let pagesWithSidebarLinks = 0;

function walk(dir) {
  for (const entry of readdirSync(dir)) {
    const full = join(dir, entry);
    if (statSync(full).isDirectory()) {
      if (entry === "static") continue;
      walk(full);
    } else if (entry.endsWith(".html") && entry !== "404.html") {
      pages++;
      const html = readFileSync(full, "utf8");
      const menu = html.match(/<aside[^>]*rspress-sidebar[\s\S]*?<\/aside>/);
      const links = menu ? (menu[0].match(/<a /g) ?? []).length : 0;
      if (links > 0) pagesWithSidebarLinks++;
    }
  }
}

walk(docBuild);

const ratio = pages === 0 ? 0 : pagesWithSidebarLinks / pages;
console.log(
  `[check-sidebar] pages with sidebar links: ${pagesWithSidebarLinks}/${pages}`,
);
if (pages === 0 || ratio < 0.9) {
  console.error(
    `[check-sidebar] FAIL: sidebar links missing on most pages ` +
      `(threshold 90%). Is themeConfig.nav/sidebar hand-defined in ` +
      `rspress.config.ts, or did gen:api fail?`,
  );
  process.exit(1);
}
